      "fullText" : "كثير متضايقين  \nاكلوهم بدل ماتصوروهم، اتركوا الحيوانات بحالهم..الخ ، أولًا بحيرة البط من أبرز معالم كورنيش الخبر و وجهة سياحية مشتغلة عليها امانة الشرقية طبيعي تكون مليانة ناس و موفرين لهم اكل و مويا داخل البحيرة، البس مرات يخرج لبرى عند الناس وقتها يحصل التجمهر https://t.co/JHgpyURwaG",
