      "fullText" : "ربي في #يوم_الجمعه تمم لي أموري القادمه على خير، و بشرني بما أنتظره منك فأنت خير المبشّرين، اللهم أرح قلبي وهون علي ما أثقلني كتمانه وإسقني صبراً، يارب أجعل كل ما دعيته لك سراً وجهراً تكتبه لي واقعاً يفرح به قلبي، يارب إني وكلتك امري فكن لي خير وكيل ودبر لي امري يارب العالمين 💛.",
